function rampartSimulate(createStrategy, seed, maxTicks) {
  "use strict";
  // Optional 4th argument: a passive recorder { event(kind, ...), tick(tick, view) } used only by the
  // replay renderer. It observes the simulation and never changes it.
  var rec = arguments.length > 3 ? arguments[3] : null;

  var TNAMES = ["bolt", "cannon", "frost", "lance", "flak"];
  var TDEF = {
    bolt:   { idx: 0, cost: 50,  dmg: 26,  period: 8,  range: 300, splash: 0,  slow: 0,  pierce: 0, ground: 1, air: 1 },
    cannon: { idx: 1, cost: 90,  dmg: 60,  period: 24, range: 260, splash: 90, slow: 0,  pierce: 0, ground: 1, air: 0 },
    frost:  { idx: 2, cost: 70,  dmg: 10,  period: 12, range: 240, splash: 0,  slow: 30, pierce: 0, ground: 1, air: 1 },
    lance:  { idx: 3, cost: 120, dmg: 180, period: 36, range: 360, splash: 0,  slow: 0,  pierce: 1, ground: 1, air: 0 },
    flak:   { idx: 4, cost: 80,  dmg: 40,  period: 10, range: 320, splash: 70, slow: 0,  pierce: 0, ground: 0, air: 1 }
  };
  var ENAMES = ["grunt", "runner", "wisp", "brute", "splitter", "mender"];
  var EDEF = {
    grunt:     { hp: 60,  speed: 10, bounty: 4, leak: 1, air: 0, first: 1, weight: 10 },
    runner:    { hp: 40,  speed: 20, bounty: 4, leak: 1, air: 0, first: 2, weight: 4 },
    wisp:      { hp: 50,  speed: 12, bounty: 6, leak: 2, air: 1, first: 3, weight: 3 },
    brute:     { hp: 150, speed: 6,  bounty: 9, leak: 3, air: 0, first: 4, weight: 3 },
    splitter:  { hp: 90,  speed: 8,  bounty: 6, leak: 2, air: 0, first: 6, weight: 2 },
    mender:    { hp: 70,  speed: 8,  bounty: 7, leak: 2, air: 0, first: 8, weight: 1 },
    splitling: { hp: 0,   speed: 12, bounty: 1, leak: 1, air: 0, first: 0, weight: 0 }
  };
  var GROUND_PTS = [[0, 2], [6, 2], [6, 10], [12, 10], [12, 3], [18, 3], [18, 11], [23, 11]];
  var AIR_PTS = [[0, 6], [21, 6], [21, 11], [23, 11]];
  var SLOTS = [[3, 3], [5, 5], [7, 4], [7, 8], [9, 9], [10, 5], [11, 8], [13, 8], [14, 5], [15, 2], [16, 7], [17, 4], [19, 8], [20, 10], [22, 9], [3, 7]];

  function mulberry32(a) {
    return function () {
      a = (a + 0x6D2B79F5) | 0;
      var t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return (t ^ (t >>> 14)) >>> 0;
    };
  }

  function makeRoute(pts, statedLen) {
    var segs = [], acc = 0, i;
    for (i = 0; i + 1 < pts.length; i++) {
      var ax = pts[i][0] * 100 + 50, ay = pts[i][1] * 100 + 50;
      var bx = pts[i + 1][0] * 100 + 50, by = pts[i + 1][1] * 100 + 50;
      var len = Math.abs(bx - ax) + Math.abs(by - ay);
      segs.push({ ax: ax, ay: ay, dx: bx > ax ? 1 : bx < ax ? -1 : 0, dy: by > ay ? 1 : by < ay ? -1 : 0, start: acc, len: len });
      acc += len;
    }
    return { segs: segs, len: statedLen };
  }
  function place(e) {
    var segs = e.route.segs, p = e.progress, i = 0;
    while (i < segs.length - 1 && p > segs[i].start + segs[i].len) i++;
    var s = segs[i], d = p - s.start;
    if (d > s.len) d = s.len;
    e.x = s.ax + s.dx * d;
    e.y = s.ay + s.dy * d;
  }
  var ROUTE_G = makeRoute(GROUND_PTS, 4600);
  var ROUTE_A = makeRoute(AIR_PTS, 2600);

  var mult = [0, 1000];
  function hpMult(w) {
    while (mult.length <= w) mult.push(Math.floor(mult[mult.length - 1] * 108 / 100));
    return mult[w];
  }

  var rng = mulberry32(seed);
  function genWave(w) {
    var n = 4 + Math.floor(3 * w / 5), avail = [], total = 0, out = [], i, j;
    for (i = 0; i < ENAMES.length; i++) {
      if (EDEF[ENAMES[i]].first <= w) { avail.push(ENAMES[i]); total += EDEF[ENAMES[i]].weight; }
    }
    for (i = 0; i < n; i++) {
      var r = rng() % total;
      for (j = 0; j < avail.length; j++) {
        var wt = EDEF[avail[j]].weight;
        if (r < wt) { out.push(avail[j]); break; }
        r -= wt;
      }
    }
    return out;
  }

  var gold = 250, baseHp = 10, wave = 0, fallTick = -1, nextId = 1;
  var turrets = [], enemies = [], queue = [], log = [], waves = {};
  var i;
  for (i = 0; i < 16; i++) turrets.push(null);
  waves[1] = genWave(1);
  var strat = createStrategy();
  var hasTarget = !!strat && typeof strat.target === "function";

  function newEnemy(type, w, maxHp, progress) {
    var d = EDEF[type];
    var e = {
      id: nextId++, type: type, def: d, wave: w, maxHp: maxHp, hp: maxHp,
      armor: type === "grunt" ? Math.floor(w / 4) : type === "brute" ? 6 + w : 0,
      progress: progress, slow: 0, age: 0, route: d.air ? ROUTE_A : ROUTE_G, x: 0, y: 0
    };
    place(e);
    enemies.push(e);
    return e;
  }
  function view(e) {
    return {
      id: e.id, type: e.type, hp: e.hp, maxHp: e.maxHp, x: e.x, y: e.y, air: e.def.air,
      armor: e.armor, speed: e.def.speed, slowed: e.slow, remaining: e.route.len - e.progress
    };
  }
  function tierDamage(d, tier) {
    var v = d.dmg;
    if (tier >= 2) v = Math.floor(v * 16 / 10);
    if (tier >= 3) v = Math.floor(v * 16 / 10);
    return v;
  }
  function makeState(tick) {
    var slots = [], evs = [], k;
    for (k = 0; k < 16; k++) {
      var t = turrets[k];
      slots.push({
        slot: k, x: SLOTS[k][0] * 100 + 50, y: SLOTS[k][1] * 100 + 50,
        turret: t ? { type: t.type, tier: t.tier, spent: t.spent } : null
      });
    }
    for (k = 0; k < enemies.length; k++) evs.push(view(enemies[k]));
    return { tick: tick, wave: wave, gold: gold, baseHp: baseHp, slots: slots, enemies: evs, nextWave: waves[wave + 1].slice() };
  }
  function applyActions(tick, actions) {
    if (!Array.isArray(actions)) return;
    var n = Math.min(32, actions.length), k;
    for (k = 0; k < n; k++) {
      var a = actions[k];
      if (!a || typeof a !== "object") continue;
      var s = a.slot;
      if (typeof s !== "number" || s !== Math.floor(s) || s < 0 || s > 15) continue;
      var t = turrets[s], d, cost;
      if (a.op === "build") {
        if (t || typeof a.type !== "string" || !Object.prototype.hasOwnProperty.call(TDEF, a.type)) continue;
        d = TDEF[a.type];
        if (gold < d.cost) continue;
        gold -= d.cost;
        turrets[s] = { type: a.type, def: d, tier: 1, spent: d.cost, cd: 0, x: SLOTS[s][0] * 100 + 50, y: SLOTS[s][1] * 100 + 50 };
        log.push([tick, "B", s, d.idx]);
        if (rec) rec.event("B", tick, s, d.idx);
      } else if (a.op === "upgrade") {
        if (!t || t.tier >= 3) continue;
        cost = t.tier === 1 ? t.def.cost : 2 * t.def.cost;
        if (gold < cost) continue;
        gold -= cost;
        t.tier += 1;
        t.spent += cost;
        log.push([tick, "U", s, t.tier]);
        if (rec) rec.event("U", tick, s, t.tier);
      } else if (a.op === "sell") {
        if (!t) continue;
        gold += Math.floor(t.spent * 70 / 100);
        turrets[s] = null;
        log.push([tick, "S", s, 0]);
        if (rec) rec.event("S", tick, s, t.def.idx, t.tier);
      }
    }
  }

  var tick, k, e, fell = false;
  for (tick = 0; tick < maxTicks && !fell; tick++) {
    // 1. wave start
    if (tick >= 20 && (tick - 20) % 40 === 0) {
      wave = (tick - 20) / 40 + 1;
      gold += Math.min(50, Math.floor(gold * 5 / 100)) + 10 + 2 * wave;
      waves[wave + 1] = genWave(wave + 1);
      if (rec) rec.event("W", tick, wave, waves[wave + 1]);
      applyActions(tick, strat.plan(makeState(tick)));
      var comp = waves[wave];
      for (k = 0; k < comp.length; k++) queue.push({ tick: tick + 4 * k, wave: wave, index: k, type: comp[k] });
      queue.sort(function (p, q) { return p.tick - q.tick || p.wave - q.wave || p.index - q.index; });
      delete waves[wave];
    }
    // 2. spawn
    while (queue.length && queue[0].tick <= tick) {
      var q = queue.shift();
      newEnemy(q.type, q.wave, Math.floor(EDEF[q.type].hp * hpMult(q.wave) / 1000), 0);
    }
    // 3. move
    for (k = 0; k < enemies.length; k++) {
      e = enemies[k];
      e.progress += e.slow > 0 ? Math.floor(e.def.speed * 60 / 100) : e.def.speed;
      if (e.progress >= e.route.len) {
        baseHp -= e.def.leak;
        enemies.splice(k, 1);
        k--;
        log.push([tick, "L", e.id, baseHp]);
        if (rec) rec.event("L", tick, e.id, baseHp);
        if (baseHp <= 0) {
          log.push([tick, "F", wave, 0]);
          if (rec) rec.event("F", tick, wave, 0);
          fallTick = tick;
          fell = true;
          break;
        }
      } else {
        place(e);
      }
    }
    if (!fell) {
      // 4. age & heal
      for (k = 0; k < enemies.length; k++) {
        e = enemies[k];
        e.age += 1;
        if (e.type === "mender" && e.age % 20 === 0) {
          for (var j = 0; j < enemies.length; j++) {
            var o = enemies[j], hx = o.x - e.x, hy = o.y - e.y;
            if (hx * hx + hy * hy <= 150 * 150) {
              o.hp = Math.min(o.maxHp, o.hp + Math.floor(o.maxHp * 8 / 100));
            }
          }
          if (rec) rec.event("H", tick, e.id, e.x, e.y);
        }
      }
      // 5. turrets fire
      for (var s = 0; s < 16; s++) {
        var t = turrets[s];
        if (!t) continue;
        if (t.cd > 0) { t.cd -= 1; if (t.cd > 0) continue; }
        var d = t.def, range = d.range + 30 * (t.tier - 1), r2 = range * range, cands = [];
        for (k = 0; k < enemies.length; k++) {
          e = enemies[k];
          if (e.def.air ? !d.air : !d.ground) continue;
          var dx = e.x - t.x, dy = e.y - t.y;
          if (dx * dx + dy * dy <= r2) cands.push(e);
        }
        if (!cands.length) continue;
        var tgt = null;
        if (hasTarget) {
          var views = [];
          for (k = 0; k < cands.length; k++) views.push(view(cands[k]));
          var pick = strat.target({ slot: s, type: t.type, tier: t.tier, x: t.x, y: t.y, range: range }, views);
          for (k = 0; k < cands.length; k++) if (cands[k].id === pick) { tgt = cands[k]; break; }
        }
        if (!tgt) {
          tgt = cands[0];
          for (k = 1; k < cands.length; k++) {
            if (cands[k].route.len - cands[k].progress < tgt.route.len - tgt.progress) tgt = cands[k];
          }
        }
        var dmg = tierDamage(d, t.tier), tx = tgt.x, ty = tgt.y, hits = [];
        if (d.splash > 0) {
          var sp2 = d.splash * d.splash;
          for (k = 0; k < enemies.length; k++) {
            e = enemies[k];
            if (e.def.air ? !d.air : !d.ground) continue;
            var sx = e.x - tx, sy = e.y - ty;
            if (sx * sx + sy * sy <= sp2) hits.push(e);
          }
        } else {
          hits.push(tgt);
        }
        for (k = 0; k < hits.length; k++) {
          e = hits[k];
          e.hp -= d.pierce ? dmg : Math.max(1, dmg - e.armor);
          if (d.slow > 0) e.slow = d.slow;
        }
        t.cd = d.period;
        if (rec) rec.event("X", tick, s, d.idx, tgt.id, tx, ty, tgt.def.air);
        // remove the dead in ascending id order (splitlings are appended with new, larger ids)
        for (k = 0; k < enemies.length; k++) {
          e = enemies[k];
          if (e.hp > 0) continue;
          enemies.splice(k, 1);
          k--;
          gold += e.def.bounty;
          log.push([tick, "K", e.id, s]);
          if (rec) rec.event("K", tick, e.id, s, e.x, e.y, e.type);
          if (e.type === "splitter") {
            var chp = Math.max(1, Math.floor(e.maxHp / 4));
            for (var c = 0; c < 3; c++) {
              var child = newEnemy("splitling", e.wave, chp, e.progress);
              if (rec) rec.event("P", tick, child.id, e.id);
            }
          }
        }
      }
      // 6. slow timers
      for (k = 0; k < enemies.length; k++) if (enemies[k].slow > 0) enemies[k].slow -= 1;
    }
    if (rec) rec.tick(tick, { wave: wave, gold: gold, baseHp: baseHp, enemies: enemies, turrets: turrets, nextWave: waves[wave + 1] || [], fell: fell });
  }

  var endTick = fallTick >= 0 ? fallTick : maxTicks;
  var str = JSON.stringify(log), h = 0x811c9dc5;
  for (i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  var hex = (h >>> 0).toString(16);
  while (hex.length < 8) hex = "0" + hex;
  return { score: Math.round((endTick - 20) * 100 / 40) / 100, fallTick: fallTick, log: log, hash: hex };
}

