const path = require('path');
const src = fs.readFileSync(path.join(__dirname, process.argv[2] || 'sim.js'), 'utf8');
const rampartSimulate = new Function(src + '\nreturn rampartSimulate;')();

const A = () => ({ plan(s) { const a = []; let g = s.gold; for (const sl of s.slots) if (!sl.turret && g >= 50) { a.push({ op: "build", slot: sl.slot, type: "bolt" }); g -= 50; } return a; } });
const B = () => ({ plan(s) {
  if (s.wave === 1) return [{op:"build",slot:3,type:"cannon"},{op:"build",slot:6,type:"frost"}];
  if (s.wave === 3) return [{op:"upgrade",slot:3},{op:"build",slot:12,type:"flak"}];
  if (s.wave === 6) return [{op:"build",slot:8,type:"lance"},{op:"sell",slot:6}];
  return [];
} });
