// usage: node run.js <stratFile> <paramsJSON> <seedList e.g. 1-20 or 1,5,9> [verbose]
const fs = require('fs');
const path = require('path');
const simSrc = fs.readFileSync(path.join(__dirname, 'sim.js'), 'utf8');
const rampartSimulate = new Function(simSrc + '\nreturn rampartSimulate;')();

function loadStrategy(file, params) {
  let src = fs.readFileSync(path.join(__dirname, file), 'utf8');
  src = src.replace(/\/\*PARAMS\*\/[\s\S]*?\/\*END\*\//, JSON.stringify(params));
  return new Function(src + '\nreturn createStrategy;')();
}
function parseSeeds(s) {
  const out = [];
  for (const part of String(s).split(',')) {
    if (part.includes('-')) { const [a, b] = part.split('-').map(Number); for (let i = a; i <= b; i++) out.push(i); }
    else out.push(Number(part));
  }
  return out;
}
function runOne(createStrategy, seed, verbose) {
  let dbg = null;
  const wrapped = () => { const s = createStrategy(); dbg = s._dbg || null; return s; };
  const t0 = process.hrtime.bigint();
  const r = rampartSimulate(wrapped, seed, 12020);
  const ms = Number(process.hrtime.bigint() - t0) / 1e6;
  return { seed, score: r.score, ms, hash: r.hash, dbg };
}
module.exports = { loadStrategy, parseSeeds, runOne, rampartSimulate };

if (require.main === module) {
  const file = process.argv[2], params = JSON.parse(process.argv[3] || '{}'), seeds = parseSeeds(process.argv[4] || '1-10');
  const verbose = process.argv[5];
  const cs = loadStrategy(file, params);
  let sum = 0, tms = 0, mx = 0;
  for (const seed of seeds) {
    const r = runOne(cs, seed, verbose);
    sum += r.score; tms += r.ms; mx = Math.max(mx, r.ms);
    if (verbose) {
      console.log(`seed ${seed} score ${r.score} ms ${r.ms.toFixed(0)} ` + (r.dbg ? `desync ${r.dbg.desync} miss ${r.dbg.shotMiss} sims ${r.dbg.sims} ticks ${r.dbg.ticks}` : ''));
      if (verbose === '2' && r.dbg) console.log(r.dbg.history.map(h => 'w' + h[0] + ': ' + h[1]).join('\n'));
    }
  }
  console.log(`mean ${(sum / seeds.length).toFixed(3)} over ${seeds.length} seeds, avg ms ${(tms / seeds.length).toFixed(0)}, max ms ${mx.toFixed(0)}`);
}

