  var NBG = (GLEN >> 4) + 16, NBA = (ALEN >> 4) + 16;
  var HB = new Float64Array(NBG + 2);
  var CAND = new Int32Array(CAP);
  var HEAL = new Int32Array(CAP);

  // one tick, steps 2..6 of the rules (the wave-start step is done by the caller). rec: optional array, gets (slot, targetId) per shot
  function stepTick(S, rec) {
    var tick = S.tick, n = S.n, i, j = 0, ty, p, k;
    var eid = S.eid, ety = S.ety, ehp = S.ehp, emx = S.emx, ear = S.ear, epr = S.epr, esl = S.esl, eag = S.eag, ewv = S.ewv;
