        for (i = 0; i < n; i++) {
          if (ety[i] !== 2) continue;
          if (d2a[epr[i]] <= r2) CAND[nc++] = i;
        }
        if (!nc) continue;
        if (nc === 1) best = CAND[0];
        else {
          for (b = 0; b < NBA; b++) HB[b] = 0;
          for (i = 0; i < n; i++) {
            if (ety[i] !== 2) continue;
            hp = ehp[i];
            HB[(epr[i] >> 4) + 8] += dmg < hp ? dmg : hp;
          }
          for (b = 1; b < NBA; b++) HB[b] += HB[b - 1];
          for (k = 0; k < nc; k++) {
            i = CAND[k]; p = epr[i]; b = (p >> 4) + 8;
