  // ------------------------------------------------------------------ wave compositions (known + sampled)
  var comps = {};
  comps[1] = [0, 0, 0, 0];
  var known = { 1: true };
  function mulberry(a) {
    return function () {
      a = (a + 0x6D2B79F5) | 0;
      var t = Math.imul(a ^ (a >>> 15), 1 | a);
