  }
  var SAMPLE_MODE = par("sampleMode", 0);
  function sampleComp(w) {
    var n = 4 + Math.floor(3 * w / 5), total = 0, t, i, out = [], rnd = mulberry(977 * w + 31337);
    for (t = 0; t < 6; t++) if (E_FIRST[t] <= w) total += E_WEIGHT[t];
