// ------------------------------------------------------------------ look-ahead test
var S = newState();          // the shadow of the real game
S.tick = 20;
var W = newState(), C = newState(), R = newState();
var K_TRACK = par("kTrack", 1), TEST_MAX = par("testMax", 600), ALIVE_PEN = par("alivePen", 0.25);
var simCount = 0, tickCount = 0;

// Simulates from `src` (state at a wave start, after payment and purchases, before its spawns are queued)
// and reports how far the enemies of the known waves get. Lower is better; >= 1 means leaks.
function runTest(src, limit) {
  var w = src.wave, i, n, tr = 0;
  copyState(R, src);
  R.noFall = true; R.trackW = w + K_TRACK; R.pen = 0; R.penSum = 0; R.leakDmg = 0; R.penG = 0; R.penA = 0;
  for (i = 0, n = R.n; i < n; i++) if (R.ety[i] !== DEAD) tr++;
  for (i = 0; i <= K_TRACK; i++) tr += comp(w + i).length;
  for (i = 0; i < R.sw.length; i++) tr += R.sw[i].comp.length - R.sw[i].next;
  R.trackedLeft = tr;
  queueWave(R, w, comp(w));
  var end = R.tick + TEST_MAX, m = 0;
  simCount++;
  while (R.trackedLeft > 0 && R.tick < end) {
    if (R.tick > src.tick && (R.tick - 20) % 40 === 0) {
      payWave(R, R.wave + 1);
      queueWave(R, R.wave, comp(R.wave));
    }
    stepTick(R, null);
    tickCount++;
    if (R.leakDmg + R.pen > limit) break;
  }
  m = R.leakDmg + R.pen;
  if (R.trackedLeft > 0 && m <= limit) {
    // enemies of the tracked waves still alive at the horizon
    var worst = 0;
    for (i = 0, n = R.n; i < n; i++) {
      if (R.ety[i] === DEAD || R.ewv[i] > R.trackW) continue;
      var f = (R.ety[i] === 2 ? R.epr[i] / ALEN : R.epr[i] / GLEN) + ALIVE_PEN;
      if (f > worst) worst = f;
    }
    if (worst > R.pen) m = R.leakDmg + worst;
  }
  return m + 1e-4 * R.penSum;
}

// ------------------------------------------------------------------ purchase policy
var THETA = par("theta", 0.85), THETA_LO = par("thetaLo", 0.8), MAX_ROUNDS = par("maxRounds", 12);
var TYPE_BIAS = par("typeBias", [1, 1, 1, 1, 1]);
var history = [];

function decide(w) {
  var acts = [], rounds = 0, s, t;
  copyState(W, S);
  var cur = runTest(W, 1e9);
  if (cur <= THETA) return acts;
  while (cur > THETA_LO && rounds < MAX_ROUNDS && acts.length < 30) {
    rounds++;
    var bestR = 0, bestK = -1, bestS = -1, bestT = -1, bestM = 0, m, cost, ratio;
    for (s = 0; s < 16; s++) {
      if (W.tty[s] < 0) {
        for (t = 0; t < 5; t++) {
          cost = T_COST[t];
          if (W.gold < cost) continue;
          copyState(C, W);
          applyAct(C, 0, s, t);
          m = runTest(C, cur);
          ratio = (cur - m) * TYPE_BIAS[t] / cost;
          if (ratio > bestR) { bestR = ratio; bestK = 0; bestS = s; bestT = t; bestM = m; }
        }
      } else if (W.ttr[s] < 3) {
        t = W.tty[s];
        cost = W.ttr[s] === 1 ? T_COST[t] : 2 * T_COST[t];
        if (W.gold < cost) continue;
        copyState(C, W);
        applyAct(C, 1, s, 0);
        m = runTest(C, cur);
        ratio = (cur - m) * TYPE_BIAS[t] / cost;
        if (ratio > bestR) { bestR = ratio; bestK = 1; bestS = s; bestT = t; bestM = m; }
      }
    }
    if (bestK < 0) break;
    applyAct(W, bestK, bestS, bestT);
    acts.push(bestK === 0 ? { op: "build", slot: bestS, type: TNAMES[bestT] } : { op: "upgrade", slot: bestS });
    cur = bestM;
  }
  return acts;
}

// ------------------------------------------------------------------ strategy object
var desync = false, shots = [], shotPos = 0, dbg = { desync: 0, sims: 0, ticks: 0, history: history, shotMiss: 0 };
var TYPE_IDX = { grunt: 0, runner: 1, wisp: 2, brute: 3, splitter: 4, mender: 5 };

