// usage: node run.js <stratFile|parts> <paramsJSON> <seedList e.g. 1-20 or 1,5,9> [verbose]
const fs = require('fs');
const path = require('path');
const simSrc = fs.readFileSync(path.join(__dirname, 'sim.js'), 'utf8');
const rampartSimulate = new Function(simSrc + '\nreturn rampartSimulate;')();

function stratSource(file) {
  if (file === 'parts' || file.startsWith('parts:')) {
    // parts[:policyFile]
    const pol = file.includes(':') ? file.split(':')[1] : 'policy.js';
    return ['head.js', pol, 'tail.js'].map(f => fs.readFileSync(path.join(__dirname, 'parts', f), 'utf8')).join('');
  }
  return fs.readFileSync(path.join(__dirname, file), 'utf8');
}
function loadStrategy(file, params) {
  let src = stratSource(file);
  src = src.replace(/\/\*PARAMS\*\/[\s\S]*?\/\*END\*\//, JSON.stringify(params));
  return new Function(src + '\nreturn createStrategy;')();
