// Free-config experiments with the fast engine: place a full config for free at wave `startWave` and see how long it holds.
const { loadStrategy, parseSeeds } = require('./run.js');

function mulberry32(a) { return function () { a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }
const FIRST = [1, 2, 3, 4, 6, 8], WEIGHT = [10, 4, 3, 3, 2, 1];
function genWaves(seed, count) {
  const rng = mulberry32(seed), waves = [null];
  for (let w = 1; w <= count; w++) {
    const n = 4 + Math.floor(3 * w / 5); let total = 0; const out = [];
    for (let t = 0; t < 6; t++) if (FIRST[t] <= w) total += WEIGHT[t];
    for (let i = 0; i < n; i++) { let r = rng() % total; for (let t = 0; t < 6; t++) { if (FIRST[t] > w) continue; if (r < WEIGHT[t]) { out.push(t); break; } r -= WEIGHT[t]; } }
    waves.push(out);
  }
  return waves;
}
const waveCache = {};
function wavesFor(seed) { return waveCache[seed] || (waveCache[seed] = genWaves(seed, 120)); }

const TYPE_CH = { b: 0, c: 1, f: 2, l: 3, k: 4, '-': -1 };  // k = flak
function parseCfg(str) { // e.g. "c3 b3 ..." 16 entries
  return str.trim().split(/\s+/).map(x => [TYPE_CH[x[0]], Number(x[1] || 0)]);
}
// returns fall tick
function holdTest(api, cfg, seed, startWave) {
  const S = api.newState(), waves = wavesFor(seed);
  for (let s = 0; s < 16; s++) { S.tty[s] = cfg[s][0]; S.ttr[s] = cfg[s][0] < 0 ? 0 : cfg[s][1]; }
  S.tick = 20 + 40 * (startWave - 1); S.wave = startWave - 1;
  while (!S.fell && S.tick < 20 + 40 * 110) {
    if ((S.tick - 20) % 40 === 0) { api.payWave(S, S.wave + 1); api.queueWave(S, S.wave, waves[S.wave]); }
    api.stepTick(S, null);
  }
  return S.fallTick < 0 ? S.tick : S.fallTick;
}
function evalCfg(api, cfg, seeds, startWave) {
  let sum = 0;
  for (const seed of seeds) sum += (holdTest(api, cfg, seed, startWave) - 20) / 40;
  return sum / seeds.length;
}
function cfgStr(cfg) { const ch = 'bcflk'; return cfg.map(c => c[0] < 0 ? '--' : ch[c[0]] + c[1]).join(' '); }
function cfgCost(cfg) { const C = [50, 90, 70, 120, 80]; let t = 0; for (const c of cfg) if (c[0] >= 0) t += C[c[0]] * [0, 1, 2, 4][c[1]]; return t; }
module.exports = { genWaves, wavesFor, parseCfg, holdTest, evalCfg, cfgStr, cfgCost };

if (require.main === module) {
  const params = JSON.parse(process.argv[2] || '{}'); params.debug = 1;
  const seeds = parseSeeds(process.argv[3] || '101-110');
  const mode = process.argv[4] || 'search';
  const startWave = Number(process.argv[6] || 1);
  const api = loadStrategy('parts', params)()._api;
  if (mode === 'eval') {
    for (const str of process.argv[5].split('|')) {
      const cfg = parseCfg(str);
      console.log(evalCfg(api, cfg, seeds, startWave).toFixed(3), cfgCost(cfg), cfgStr(cfg));
    }
  } else {
    // local search over types at tier 3
    let cfg = parseCfg(process.argv[5] || 'c3 c3 c3 c3 c3 c3 c3 c3 c3 c3 c3 c3 c3 c3 c3 c3');
    let best = evalCfg(api, cfg, seeds, startWave);
    console.log('start', best.toFixed(3), cfgStr(cfg));
    let improved = true;
    while (improved) {
      improved = false;
      for (let s = 0; s < 16; s++) {
        let bt = cfg[s][0];
        for (let t = 0; t < 5; t++) {
          if (t === cfg[s][0]) continue;
          const old = cfg[s][0]; cfg[s][0] = t;
          const v = evalCfg(api, cfg, seeds, startWave);
          if (v > best + 1e-9) { best = v; bt = t; improved = true; console.log(best.toFixed(3), cfgCost(cfg), cfgStr(cfg)); }
          cfg[s][0] = old;
        }
        cfg[s][0] = bt;
      }
    }
    console.log('final', best.toFixed(3), cfgCost(cfg), cfgStr(cfg));
  }
}

