// Randomised local search over full tier-3 configs. usage: node cfgsa.js <rngSeed> <seconds> <seeds> [paramsJSON] [startCfg]
const { loadStrategy, parseSeeds } = require('./run.js');
const cfgm = require('./cfg.js');
const rngSeed = Number(process.argv[2] || 1), seconds = Number(process.argv[3] || 60);
const seeds = parseSeeds(process.argv[4] || '101-112');
const params = JSON.parse(process.argv[5] || '{}'); params.debug = 1;
const api = loadStrategy('parts', params)()._api;
let a = rngSeed * 7919 + 13;
function rnd() { a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }
const t0 = Date.now();
let globalBest = -1, globalCfg = null;
const cache = new Map();
function ev(cfg) {
  const k = cfgm.cfgStr(cfg);
  if (cache.has(k)) return cache.get(k);
  const v = cfgm.evalCfg(api, cfg, seeds, 1);
  cache.set(k, v);
  return v;
}
while ((Date.now() - t0) / 1000 < seconds) {
  // random start biased to cannon/flak
  let cfg;
  if (process.argv[6] && globalCfg === null) cfg = cfgm.parseCfg(process.argv[6]);
  else { cfg = []; for (let s = 0; s < 16; s++) { const r = rnd(); cfg.push([r < 0.45 ? 1 : r < 0.75 ? 4 : r < 0.85 ? 0 : r < 0.93 ? 2 : 3, 3]); } }
  let best = ev(cfg), improved = true;
  while (improved && (Date.now() - t0) / 1000 < seconds) {
    improved = false;
    const order = [...Array(16).keys()].sort(() => rnd() - 0.5);
    for (const s of order) {
      let bt = cfg[s][0];
      for (let t = 0; t < 5; t++) {
        if (t === cfg[s][0]) continue;
        const old = cfg[s][0]; cfg[s][0] = t;
        const v = ev(cfg);
        if (v > best + 1e-9) { best = v; bt = t; improved = true; }
        cfg[s][0] = old;
      }
      cfg[s][0] = bt;
    }
    // pair swaps
    for (let i = 0; i < 16; i++) for (let j = i + 1; j < 16; j++) {
      if (cfg[i][0] === cfg[j][0]) continue;
      const ti = cfg[i][0], tj = cfg[j][0];
      cfg[i][0] = tj; cfg[j][0] = ti;
      const v = ev(cfg);
      if (v > best + 1e-9) { best = v; improved = true; } else { cfg[i][0] = ti; cfg[j][0] = tj; }
    }
  }
  if (best > globalBest) { globalBest = best; globalCfg = cfgm.cfgStr(cfg); }
  console.log('local', best.toFixed(3), cfgm.cfgCost(cfg), cfgm.cfgStr(cfg));
}
console.log('BEST', globalBest.toFixed(3), globalCfg);

