// Parallel sweep. usage: node sweep.js <strat> <seeds> <baseJSON> <variantsJSON array of overrides | @file>
// worker mode: node sweep.js --worker <strat> <paramsJSON> <seedsCSV>
const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');
const { loadStrategy, parseSeeds, runOne } = require('./run.js');

if (process.argv[2] === '--worker') {
  const cs = loadStrategy(process.argv[3], JSON.parse(process.argv[4]));
  const out = [];
  for (const seed of parseSeeds(process.argv[5])) { const r = runOne(cs, seed, false); out.push([seed, r.score, Math.round(r.ms), r.dbg ? r.dbg.desync + r.dbg.shotMiss : 0]); }
  process.stdout.write(JSON.stringify(out));
} else {
  const strat = process.argv[2], seeds = parseSeeds(process.argv[3]);
  const base = JSON.parse(process.argv[4] || '{}');
  let varg = process.argv[5] || '[{}]';
  if (varg[0] === '@') varg = fs.readFileSync(varg.slice(1), 'utf8');
  const variants = JSON.parse(varg);
  const PAR = Number(process.env.PAR || 10), CH = Number(process.env.CHUNK || 3);
  const jobs = [];
  variants.forEach((v, vi) => { for (let i = 0; i < seeds.length; i += CH) jobs.push({ vi, seeds: seeds.slice(i, i + CH) }); });
  const results = variants.map(() => []);
  let next = 0, running = 0, done = 0;
  const t0 = Date.now();
  function launch() {
    while (running < PAR && next < jobs.length) {
      const job = jobs[next++];
      const params = Object.assign({ debug: 1 }, base, variants[job.vi]);
      const child = spawn(process.execPath, [__filename, '--worker', strat, JSON.stringify(params), job.seeds.join(',')], { env: process.env });
      let buf = '', err = '';
      child.stdout.on('data', d => buf += d);
      child.stderr.on('data', d => err += d);
      running++;
      child.on('close', () => {
        running--; done++;
        try { for (const r of JSON.parse(buf)) results[job.vi].push(r); } catch (e) { console.error('job failed', JSON.stringify(variants[job.vi]), err.slice(0, 500)); }
        if (done === jobs.length) finish(); else launch();
      });
    }
  }
  function finish() {
    const rows = variants.map((v, vi) => {
      const rs = results[vi];
      const sc = rs.map(r => r[1]);
      const mean = sc.reduce((a, b) => a + b, 0) / Math.max(1, sc.length);
      const sd = Math.sqrt(sc.reduce((a, b) => a + (b - mean) * (b - mean), 0) / Math.max(1, sc.length));
      return { v, mean, min: Math.min(...sc), max: Math.max(...sc), sd, ms: rs.reduce((a, r) => a + r[2], 0) / Math.max(1, rs.length), mxms: Math.max(...rs.map(r => r[2])), bad: rs.reduce((a, r) => a + r[3], 0), n: rs.length };
    });
    if (process.env.SORT !== '0') rows.sort((a, b) => b.mean - a.mean);
    for (const r of rows) console.log(`${r.mean.toFixed(3)}  min ${r.min.toFixed(1)} max ${r.max.toFixed(1)} sd ${r.sd.toFixed(2)} ms ${r.ms.toFixed(0)}/${r.mxms} n ${r.n}${r.bad ? ' BAD ' + r.bad : ''}  ${JSON.stringify(r.v)}`);
    console.log(`# ${((Date.now() - t0) / 1000).toFixed(1)}s`);
  }
  launch();
}

