// (1+1) random search over targeting parameters on static full builds. usage: node tune_target.js <rngSeed> <seconds> <seeds>
const { loadStrategy, parseSeeds } = require('./run.js');
const cfgm = require('./cfg.js');
const rngSeed = Number(process.argv[2] || 1), seconds = Number(process.argv[3] || 60);
const seeds = parseSeeds(process.argv[4] || '101-148');
const CFGS = ['c3 c3 c3 c3 c3 c3 c3 c3 f3 c3 k3 k3 k3 c3 k3 c3', 'c3 c3 c3 c3 c3 c3 c3 c3 f3 c3 k3 k3 k3 b3 k3 b3', 'c3 f3 c3 c3 c3 c3 c3 b3 f3 c3 k3 k3 k3 c3 f3 c3'].map(cfgm.parseCfg);
let a = rngSeed * 104729 + 7;
function rnd() { a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }
function ev(p) {
  const api = loadStrategy('parts', Object.assign({ debug: 1 }, p))()._api;
  let s = 0;
  for (const c of CFGS) s += cfgm.evalCfg(api, c, seeds, 1);
  return s / CFGS.length;
}
let cur = {
  canA: 250, canTy: [1, 2, 1, 0.7, 1.5, 2, 1.5], canProg: 0, flkA: 400, boltA: 300, boltKill: 0, boltTyW: [0, 0, 0, 0, 0, 0, 0],
  froPen: 3000, froSl: 2, froTy: [0, 0, 0, 0, 0, 0, 0], mendB: 200
};
if (process.argv[5]) cur = JSON.parse(process.argv[5]);
let best = ev(cur);
console.log('start', best.toFixed(3), JSON.stringify(cur));
const t0 = Date.now();
function mutate(p) {
  const q = JSON.parse(JSON.stringify(p));
  const n = 1 + Math.floor(rnd() * 2);
  for (let k = 0; k < n; k++) {
    const r = Math.floor(rnd() * 11);
    const mul = Math.exp((rnd() - 0.5) * 1.4);
    switch (r) {
      case 0: q.canA = Math.round(Math.max(0, q.canA * mul)); break;
      case 1: { const i = [0, 1, 3, 4, 5, 6][Math.floor(rnd() * 6)]; q.canTy[i] = Math.round(q.canTy[i] * mul * 100) / 100; break; }
      case 2: q.canProg = Math.round(Math.max(0, q.canProg + (rnd() - 0.5) * 2) * 100) / 100; break;
      case 3: q.flkA = Math.round(Math.max(0, q.flkA * mul)); break;
      case 4: q.boltA = Math.round(Math.max(0, q.boltA * mul + (rnd() - 0.5) * 100)); break;
      case 5: q.boltKill = Math.round(Math.max(0, q.boltKill + (rnd() - 0.5) * 600)); break;
      case 6: { const i = Math.floor(rnd() * 7); q.boltTyW[i] = Math.round(q.boltTyW[i] + (rnd() - 0.5) * 800); break; }
      case 7: q.froPen = Math.round(Math.max(0, q.froPen * mul)); break;
      case 8: q.froSl = Math.max(0, Math.min(20, q.froSl + Math.round((rnd() - 0.5) * 8))); break;
      case 9: { const i = Math.floor(rnd() * 7); q.froTy[i] = Math.round(q.froTy[i] + (rnd() - 0.5) * 800); break; }
      case 10: q.mendB = Math.round(Math.max(0, q.mendB + (rnd() - 0.5) * 600)); break;
    }
  }
  return q;
}
while ((Date.now() - t0) / 1000 < seconds) {
  const q = mutate(cur);
  const v = ev(q);
  if (v > best) { best = v; cur = q; console.log(best.toFixed(3), JSON.stringify(cur)); }
}
console.log('FINAL', best.toFixed(3), JSON.stringify(cur));

