// Electron probe / page tester.  usage: <electron> etest --user-data-dir=... -- <url> <outPrefix> <width> <height> <script.js>
const { app, BrowserWindow } = require('electron');
const fs = require('fs');
const path = require('path');
const args = process.argv.slice(process.argv.indexOf('--') + 1);
const url = args[0] || 'about:blank', outPrefix = args[1] || path.join(__dirname, 'shot'), W = Number(args[2] || 1280), H = Number(args[3] || 650);
const scriptFile = args[4];
setTimeout(() => { console.log('TIMEOUT'); app.exit(2); }, Number(process.env.ETEST_TIMEOUT || 60000));
app.whenReady().then(async () => {
  const win = new BrowserWindow({ width: W, height: H, show: false, useContentSize: true, webPreferences: { backgroundThrottling: false } });
  win.webContents.on('console-message', (e, level, msg, line, src) => console.log('[console:' + level + ']', msg, line || ''));
  win.webContents.on('render-process-gone', (e, d) => console.log('[gone]', JSON.stringify(d)));
  try {
    await win.loadURL(url);
    const api = {
      wait: ms => new Promise(r => setTimeout(r, ms)),
      js: code => win.webContents.executeJavaScript(code, true),
      shot: async name => { const img = await win.webContents.capturePage(); fs.writeFileSync(outPrefix + '_' + name + '.png', img.toPNG()); console.log('shot', name, JSON.stringify(img.getSize())); },
      win
    };
    if (scriptFile) await require(path.resolve(scriptFile))(api);
    else { await api.wait(1500); await api.shot('probe'); }
  } catch (e) { console.log('ERR', e && e.stack || e); }
  app.exit(0);
});

