// Headless WKWebView driver. usage: wk <fileOrUrl> <width> <height> <steps.json> <outPrefix>
// steps: [{"wait":ms} | {"js":"code"} | {"shot":"name"}]
import Cocoa
import WebKit

let args = CommandLine.arguments
guard args.count >= 6 else { print("usage: wk url w h steps.json outPrefix"); exit(1) }
let target = args[1]
let W = CGFloat(Double(args[2]) ?? 1280), H = CGFloat(Double(args[3]) ?? 650)
let stepsData = try! Data(contentsOf: URL(fileURLWithPath: args[4]))
let steps = try! JSONSerialization.jsonObject(with: stepsData) as! [[String: Any]]
let outPrefix = args[5]

class Handler: NSObject, WKScriptMessageHandler, WKNavigationDelegate {
  var onLoad: (() -> Void)?
  func userContentController(_ c: WKUserContentController, didReceive m: WKScriptMessage) {
    print("[page] \(m.body)")
  }
  func webView(_ webView: WKWebView, didFinish navigation: WKNavigation!) { print("[nav] didFinish"); onLoad?(); onLoad = nil }
  func webView(_ webView: WKWebView, didFail navigation: WKNavigation!, withError error: Error) { print("[nav] fail \(error)"); exit(3) }
  func webView(_ webView: WKWebView, didFailProvisionalNavigation navigation: WKNavigation!, withError error: Error) { print("[nav] failProvisional \(error)"); exit(3) }
  func webViewWebContentProcessDidTerminate(_ webView: WKWebView) { print("[nav] web content process terminated"); exit(4) }
}

let app = NSApplication.shared
app.setActivationPolicy(.prohibited)
let handler = Handler()
let config = WKWebViewConfiguration()
let ucc = WKUserContentController()
ucc.add(handler, name: "log")
let hook = """
(function(){
  function send(k, a){ try { window.webkit.messageHandlers.log.postMessage(k + ' ' + Array.prototype.map.call(a, function(x){ try { return typeof x === 'string' ? x : JSON.stringify(x); } catch(e) { return String(x); } }).join(' ')); } catch(e) {} }
  ['log','warn','error','info'].forEach(function(k){ var o = console[k]; console[k] = function(){ send(k, arguments); return o.apply(console, arguments); }; });
  window.addEventListener('error', function(e){ send('onerror', [e.message, e.filename, e.lineno, e.colno]); });
  window.addEventListener('unhandledrejection', function(e){ send('unhandledrejection', [String(e.reason)]); });
})();
"""
ucc.addUserScript(WKUserScript(source: hook, injectionTime: .atDocumentStart, forMainFrameOnly: true))
config.userContentController = ucc
let web = WKWebView(frame: NSRect(x: 0, y: 0, width: W, height: H), configuration: config)
web.navigationDelegate = handler
let window = NSWindow(contentRect: NSRect(x: -4000, y: -4000, width: W, height: H), styleMask: [.borderless], backing: .buffered, defer: false)
window.contentView = web
window.orderBack(nil)

var idx = 0
func next() {
  if idx >= steps.count { print("[done]"); exit(0) }
  let st = steps[idx]; idx += 1
  if let ms = st["wait"] as? Double {
    DispatchQueue.main.asyncAfter(deadline: .now() + ms / 1000.0) { next() }
  } else if let code = st["js"] as? String {
    web.evaluateJavaScript(code) { res, err in
      if let e = err { print("[js error] \(e.localizedDescription) :: \(code.prefix(80))") }
      else if let r = res { print("[js] \(r)") } else { print("[js] (undefined)") }
      next()
    }
  } else if let name = st["shot"] as? String {
    let sc = WKSnapshotConfiguration()
    sc.rect = NSRect(x: 0, y: 0, width: W, height: H)
    sc.snapshotWidth = NSNumber(value: Double(W))
    web.takeSnapshot(with: sc) { img, err in
      if let img = img, let tiff = img.tiffRepresentation, let rep = NSBitmapImageRep(data: tiff), let png = rep.representation(using: .png, properties: [:]) {
        let p = outPrefix + "_" + name + ".png"
        try? png.write(to: URL(fileURLWithPath: p))
        print("[shot] \(p) \(rep.pixelsWide)x\(rep.pixelsHigh)")
      } else { print("[shot error] \(String(describing: err))") }
      next()
    }
  } else { next() }
}
handler.onLoad = { next() }
if target.hasPrefix("http") || target.hasPrefix("file:") {
  web.load(URLRequest(url: URL(string: target)!))
} else {
  let u = URL(fileURLWithPath: target)
  web.loadFileURL(u, allowingReadAccessTo: u.deletingLastPathComponent())
}
DispatchQueue.main.asyncAfter(deadline: .now() + (Double(ProcessInfo.processInfo.environment["WK_TIMEOUT"] ?? "90") ?? 90)) { print("[timeout]"); exit(2) }
app.run()

