const DURATION = 100;
(function () {
  'use strict';
  var TPS = 20, TOTAL_TICKS = 2020;

  window.BENCH_REPORT = {
    selfCheck: { vectorA: false, vectorB: false },
    strategy: { summary: "__STRATEGY_SUMMARY__", seedsTested: 0/*__SEEDS_TESTED__*/, meanScoreOnTestedSeeds: null/*__MEAN_SCORE__*/ },
    seed42: { score: null, fallTick: null },
    systems: { board: "full", enemiesAndTurrets: "full", combatVisuals: "full", fall: "full", hud: "full", audio: "full" },
    simplifications: [/*__SIMPLIFICATIONS__*/],
    testedInBrowser: false/*__TESTED__*/,
    measuredFps: null/*__FPS__*/
  };

  // ------------------------------------------------------------------ seeded visual randomness (seed 42)
  function mulberry32(a) {
    return function () {
      a = (a + 0x6D2B79F5) | 0;
      var t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return (t ^ (t >>> 14)) >>> 0;
    };
  }
  var VR = new Float32Array(4096);
  (function () { var g = mulberry32(42); for (var i = 0; i < 4096; i++) VR[i] = g() / 4294967296; })();
  function vr(i) { return VR[i & 4095]; }
  function clamp01(x) { return x < 0 ? 0 : x > 1 ? 1 : x; }
  function smooth(x) { x = clamp01(x); return x * x * (3 - 2 * x); }
  function noise1(x, off) {            // smooth seeded value noise in [-1, 1]
    var i = Math.floor(x), f = x - i, u = f * f * (3 - 2 * f);
    var a = VR[(i + off) & 4095], b = VR[(i + 1 + off) & 4095];
    return (a + (b - a) * u) * 2 - 1;
  }

  // ------------------------------------------------------------------ board layout (display only)
  var GROUND_PTS = [[0, 2], [6, 2], [6, 10], [12, 10], [12, 3], [18, 3], [18, 11], [23, 11]];
  var AIR_PTS = [[0, 6], [21, 6], [21, 11], [23, 11]];
  var SLOT_TILES = [[3, 3], [5, 5], [7, 4], [7, 8], [9, 9], [10, 5], [11, 8], [13, 8], [14, 5], [15, 2], [16, 7], [17, 4], [19, 8], [20, 10], [22, 9], [3, 7]];
  var KEEP_X = 23.5, KEEP_Z = 11.5;
  var ENEMY_INDEX = { grunt: 0, runner: 1, wisp: 2, brute: 3, splitter: 4, mender: 5, splitling: 6 };
  function makeRoute(pts) {
    var segs = [], acc = 0;
    for (var i = 0; i + 1 < pts.length; i++) {
      var ax = pts[i][0] + 0.5, az = pts[i][1] + 0.5, bx = pts[i + 1][0] + 0.5, bz = pts[i + 1][1] + 0.5;
      var len = Math.round((Math.abs(bx - ax) + Math.abs(bz - az)) * 100);
      segs.push({ ax: ax, az: az, bx: bx, bz: bz, dx: Math.sign(bx - ax), dz: Math.sign(bz - az), start: acc, len: len });
      acc += len;
    }
    return { segs: segs, total: acc };
  }
  var ROUTE_G = makeRoute(GROUND_PTS), ROUTE_A = makeRoute(AIR_PTS);
  function routePoint(route, p, out) {
    if (p < 0) p = 0; else if (p > route.total) p = route.total;
    var segs = route.segs, i = 0;
    while (i < segs.length - 1 && p > segs[i].start + segs[i].len) i++;
    var s = segs[i], d = (p - s.start) / 100;
    out.x = s.ax + s.dx * d; out.z = s.az + s.dz * d;
    return out;
  }

