(function () {
  // Deterministic state-machine test: frames are pumped by hand through a fake requestAnimationFrame (WK_RAF=manual).
  var log = [], fails = 0;
  var $ = function (id) { return document.getElementById(id); };
  function st() {
    return { cd: $('countdown').textContent, disp: getComputedStyle($('countdown')).display, scrub: $('scrubber').value, aria: $('btn-toggle').getAttribute('aria-label'),
      pause: $('icon-pause').style.display !== 'none', play: $('icon-play').style.display !== 'none' };
  }
  function check(name, cond, extra) { if (!cond) fails++; log.push((cond ? 'ok   ' : 'FAIL ') + name + (extra !== undefined ? '  [' + extra + ']' : '')); }
  function pump(ms, n) { window.__pump(ms, n); }
  function hash(str) { var h = 0x811c9dc5; for (var i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193); } return (h >>> 0).toString(16); }
  function scrubTo(t) { var s = $('scrubber'); s.value = String(t); s.dispatchEvent(new Event('input', { bubbles: true })); return hash($('stage').toDataURL()); }
  try {
    var F = 1000 / 60, s;
    s = st(); check('markup: countdown shows 3 before first frame', s.cd === '3' && s.disp === 'block' && s.scrub === '0' && s.aria === 'Pause' && s.pause && !s.play, JSON.stringify(s));
    pump(F, 1);                      // first rAF: countdown starts, elapsed = 0
    s = st(); check('countdown start: 3', s.cd === '3' && s.disp === 'block' && s.scrub === '0');
    pump(F, 59); s = st(); check('t=0.983: still 3', s.cd === '3', s.cd);
    pump(F, 2); s = st(); check('t=1.017: 2', s.cd === '2' && s.scrub === '0', s.cd);
    pump(F, 59); s = st(); check('t=2.0: 2 or 1 boundary -> ' + s.cd, s.cd === '2' || s.cd === '1');
    pump(F, 2); s = st(); check('t=2.03: 1', s.cd === '1' && s.scrub === '0', s.cd);
    pump(F, 56); s = st(); check('t=2.97: 1 and simTime still 0', s.cd === '1' && s.scrub === '0' && s.disp === 'block', s.cd + ' ' + s.scrub);
    pump(F, 3); s = st(); check('t>=3.0: countdown hidden, playing', s.cd === '' && s.disp === 'none' && s.aria === 'Pause' && s.pause && !s.play, JSON.stringify(s));
    var a = parseFloat($('scrubber').value); pump(F, 60); var b = parseFloat($('scrubber').value);
    check('1x: 60 frames advance ~1.000s', Math.abs(b - a - 1) < 0.002, (b - a).toFixed(4));
    check('scrubber value has 3 decimals', /^\d+\.\d{3}$/.test($('scrubber').value), $('scrubber').value);
    // 120 Hz gives the same rate
    a = b; pump(1000 / 120, 120); b = parseFloat($('scrubber').value); check('120Hz: 120 frames advance ~1.000s', Math.abs(b - a - 1) < 0.002, (b - a).toFixed(4));
    // dt clamp
    a = b; pump(1500, 1); b = parseFloat($('scrubber').value); check('dt clamp: 1.5s frame advances 0.1s', Math.abs(b - a - 0.1) < 0.002, (b - a).toFixed(4));
    // pause
    $('btn-toggle').click(); s = st(); check('pause: play icon, aria Play', s.aria === 'Play' && s.play && !s.pause);
    a = parseFloat($('scrubber').value); pump(F, 30); check('paused: simTime frozen', parseFloat($('scrubber').value) === a);
