  var $ = function (id) { return document.getElementById(id); };
  var out = [];
  function run(t0, frames) {
    var s = $('scrubber'); s.value = String(t0); s.dispatchEvent(new Event('input', { bubbles: true }));
    $('btn-toggle').click();                       // PLAYING
    var gl = $('stage').getContext('webgl2') || $('stage').getContext('webgl');
    window.__pump(1000 / 60, 5); gl.finish();
    var a = performance.now(), worst = 0;
    for (var i = 0; i < frames; i++) { var f0 = performance.now(); window.__pump(1000 / 60, 1); gl.finish(); var d = performance.now() - f0; if (d > worst) worst = d; }
    var ms = (performance.now() - a) / frames;
    $('btn-toggle').click();                       // PAUSED
    out.push('t=' + t0 + ' avg ' + ms.toFixed(2) + ' ms/frame (' + (1000 / ms).toFixed(0) + ' fps throughput), worst ' + worst.toFixed(1) + ' ms');
  }
  $('btn-toggle').click();                         // leave COUNTDOWN -> PAUSED
  run(20, 120); run(60, 120); run(90, 120);
  return 'dpr=' + window.devicePixelRatio + ' size=' + window.innerWidth + 'x' + window.innerHeight + ' buf=' + $('stage').width + 'x' + $('stage').height + '\n' + out.join('\n');
})()

