function tierCost(t, from, to) {   // gold to take a turret of type t from tier `from` (0 = empty) to tier `to`
  var c = 0;
  for (var k = from + 1; k <= to; k++) c += k === 1 ? T_COST[t] : k === 2 ? T_COST[t] : 2 * T_COST[t];
  return c;
}
// puts slot s of state D at (type t, tier k), selling what is there if the type differs. Returns the list of ops.
function setSlot(D, s, t, k, ops) {
  if (D.tty[s] >= 0 && D.tty[s] !== t) { applyAct(D, 2, s, 0); if (ops) ops.push({ op: "sell", slot: s }); }
  if (D.tty[s] < 0) { if (!applyAct(D, 0, s, t)) return false; if (ops) ops.push({ op: "build", slot: s, type: TNAMES[t] }); }
  while (D.ttr[s] < k) { if (!applyAct(D, 1, s, 0)) return false; if (ops) ops.push({ op: "upgrade", slot: s }); }
  return true;
}
var best = { score: 0, s: -1, t: -1, k: 0, m: 0 };
function tryCand(s, t, k, mu, cur, floorGold) {
  var cost;
  if (W.tty[s] === t) cost = tierCost(t, W.ttr[s], k);
  else cost = tierCost(t, 0, k) - (W.tty[s] >= 0 ? Math.floor(W.tsp[s] * 70 / 100) : 0);
  if (W.gold - cost < floorGold) return;
  var eff = (cost < 20 ? 20 : cost) + COST0;
  copyState(C, W);
  if (!setSlot(C, s, t, k, null)) return;
  var m = runTest(C, cur - best.score * eff, mu);
  var sc = (cur - m) / eff;
  if (sc > best.score) { best.score = sc; best.s = s; best.t = t; best.k = k; best.m = m; }
}

function greedy(mu, floorGold, acts) {
  var rounds = 0, swaps = 0, s, t, k, i;
  var cur = runTest(W, 1e9, mu);
  while (cur > 0.5 && rounds < MAX_ROUNDS && acts.length < 26 && tickCount < TICK_BUDGET) {
    rounds++;
    best.score = 0; best.s = -1;
    var rich = W.gold - floorGold >= RICH;
    for (s = 0; s < 16; s++) {
      t = W.tty[s];
      if (t < 0) {
        tryCand(s, FINAL[s], 1, mu, cur, floorGold);
        if (rich) tryCand(s, FINAL[s], 3, mu, cur, floorGold);
      } else if (W.ttr[s] < 3) {
        tryCand(s, t, W.ttr[s] + 1, mu, cur, floorGold);
        if (rich && W.ttr[s] === 1) tryCand(s, t, 3, mu, cur, floorGold);
      }
    }
    if (best.s < 0 && floorGold === 0 && swaps < SWAP_ROUNDS) {
      // nothing left to add: try re-shaping the build (same tier, other type)
      swaps++;
      for (s = 0; s < 16; s++) {
        t = W.tty[s];
        k = t < 0 ? (rich ? 3 : 1) : W.ttr[s];
        for (i = 0; i < SWAP_TYPES.length; i++) if (SWAP_TYPES[i] !== t) tryCand(s, SWAP_TYPES[i], k, mu, cur, floorGold);
      }
      if (best.s >= 0 && cur - best.m < SWAP_MIN_GAIN) best.s = -1;
    }
    if (best.s < 0) break;
    setSlot(W, best.s, best.t, best.k, acts);
    cur = best.m;
  }
}

function decide(w) {
  var acts = [];
  copyState(W, S);
  if (tickCount >= TICK_BUDGET) {
    // safety valve: no more look-ahead, just keep building the target
    for (var s = 0; s < 16 && acts.length < 24; s++) {
      var t = W.tty[s] < 0 ? FINAL[s] : W.tty[s];
      var k = W.tty[s] < 0 ? 1 : Math.min(3, W.ttr[s] + 1);
      if (W.gold >= tierCost(t, W.tty[s] < 0 ? 0 : W.ttr[s], k)) setSlot(W, s, t, k, acts);
    }
    return acts;
  }
  greedy(HP_MARGIN, 0, acts);
  if (W.gold > BANK_CAP && HP_MARGIN2 > HP_MARGIN) greedy(HP_MARGIN2, BANK_CAP, acts);
  return acts;
}

