      for (i = 0; i < n; i++) {
        if (ety[i] !== 2) continue;
        if (d2a[epr[i]] <= r2) CAND[nc++] = i;
      }
      if (!nc) continue;
      if (nc === 1) best = CAND[0];
      else {
        HB.fill(0, 0, NBA);
        for (i = 0; i < n; i++) {
          if (ety[i] !== 2) continue;
          hp = ehp[i];
          HB[(epr[i] >> 4) + 8] += dmg < hp ? dmg : hp;
        }
        for (b = 1; b < NBA; b++) HB[b] += HB[b - 1];
        for (k = 0; k < nc; k++) {
          i = CAND[k]; p = epr[i]; b = (p >> 4) + 8;
          sc = (HB[b + 4] - HB[b - 5]) * FLK_A / dmg - (ALEN - p);
          if (sc > bs) { bs = sc; best = i; }
        }
      }
      tp = epr[best]; tx = AX[tp]; ty2 = AY[tp];
      if (rec) rec.push(s, eid[best]);
      lim = n;
