  // ------------------------------------------------------------------ strategy object
  var desync = false, shots = [], shotPos = 0, dbg = { desync: 0, sims: 0, ticks: 0, history: history, shotMiss: 0 };
  var TYPE_IDX = { grunt: 0, runner: 1, wisp: 2, brute: 3, splitter: 4, mender: 5 };

  // Used only if the shadow ever disagrees with the real game: a plain, stateless build-up of the target build.
  var FB_ORDER = [0, 10, 5, 8, 1, 4, 7, 11, 3, 6, 13, 12, 9, 2, 14, 15];
  function fallbackPlan(state) {
    var acts = [], gold = state.gold, slots = state.slots, tier = [], type = [], i, s, pass, c;
    for (i = 0; i < 16; i++) {
      var tu = slots && slots[i] ? slots[i].turret : null;
      type.push(tu ? TNAMES.indexOf(tu.type) : -1); tier.push(tu ? tu.tier : 0);
    }
    for (pass = 0; pass < 3 && acts.length < 30; pass++) {
      for (i = 0; i < 16 && acts.length < 30; i++) {
        s = FB_ORDER[i];
        if (tier[s] !== pass) continue;
        if (pass === 0) {
          c = T_COST[FINAL[s]];
          if (gold >= c) { gold -= c; tier[s] = 1; type[s] = FINAL[s]; acts.push({ op: "build", slot: s, type: TNAMES[FINAL[s]] }); }
        } else if (type[s] >= 0) {
          c = pass === 1 ? T_COST[type[s]] : 2 * T_COST[type[s]];
          if (gold >= c) { gold -= c; tier[s] = pass + 1; acts.push({ op: "upgrade", slot: s }); }
        }
      }
    }
    return acts;
  }

  function planInner(state) {
    var w = state.wave, i, n, alive = 0;
    if (P.forceDesync && w >= P.forceDesync) desync = true;
    if (desync) return fallbackPlan(state);
    if (w !== S.wave + 1 || state.tick !== S.tick || S.fell) { desync = true; dbg.desync++; return fallbackPlan(state); }
    var nx = [], nw = state.nextWave;
    for (i = 0; i < nw.length; i++) nx.push(TYPE_IDX[nw[i]]);
    comps[w + 1] = nx; known[w + 1] = true;
    payWave(S, w);
    for (i = 0, n = S.n; i < n; i++) if (S.ety[i] !== DEAD) alive++;
    if (S.gold !== state.gold || S.baseHp !== state.baseHp || alive !== state.enemies.length) { desync = true; dbg.desync++; return fallbackPlan(state); }
    var acts = decide(w), out = [];
    for (i = 0; i < acts.length && out.length < 32; i++) {
      var a = acts[i];
      var ok = a.op === "build" ? applyAct(S, 0, a.slot, TNAMES.indexOf(a.type)) : a.op === "upgrade" ? applyAct(S, 1, a.slot, 0) : applyAct(S, 2, a.slot, 0);
      if (ok) out.push(a);
    }
    if (out.length) history.push([w, out.map(function (a) { return a.op[0] + a.slot + (a.type ? a.type[0] + a.type[1] : ""); }).join(" ")]);
    queueWave(S, w, comp(w));
    shots.length = 0; shotPos = 0;
    for (i = 0; i < 40 && !S.fell; i++) stepTick(S, shots);
    dbg.sims = simCount; dbg.ticks = tickCount; dbg.work = workCount; if (typeof modeHist !== 'undefined') dbg.modeHist = modeHist;
    (dbg.perWave || (dbg.perWave = [])).push(tickCount);
    return out;
  }

  var strat = {
    plan: function (state) {
      if (P.debug) return planInner(state);
      try { return planInner(state); } catch (e) { desync = true; return []; }
    },
    target: function (turret, candidates) {
      if (desync) return undefined;
      if (shotPos < shots.length && shots[shotPos] === turret.slot) {
        var id = shots[shotPos + 1];
        shotPos += 2;
        for (var k = 0; k < candidates.length; k++) if (candidates[k].id === id) return id;
      }
      desync = true; dbg.shotMiss++;
      return undefined;
    }
  };
  if (P.debug) { S.leakLog = dbg.leakLog = []; }
  if (P.debug) strat._dbg = dbg;
  if (P.debug) strat._api = { newState: newState, copyState: copyState, stepTick: stepTick, payWave: payWave, queueWave: queueWave, applyAct: applyAct, comps: comps, T_COST: T_COST, TNAMES: TNAMES };
  return strat;
}

