  // ------------------------------------------------------------------ look-ahead test
  var S = newState();          // the shadow of the real game
  S.tick = 20;
  var W = newState(), C = newState(), R = newState();
  var K_TRACK = par("kTrack", 1), J_EXTRA = par("jExtra", 3), TEST_MAX = par("testMax", 480), HP_MARGIN = par("hpMargin", 1.0);
  var HP_MARGIN2 = par("hpMargin2", 1.5), BANK_CAP = par("bankCap", 1000);
  var PEN_W = par("penW", 0.001), FALL_BASE = 1000, FALL_LEAK_W = par("fallLeakW", 0.2), POST_FALL = par("postFall", 80);
  var WORK_SOFT = par("workSoft", 150e6), WORK_HARD = par("workHard", 200e6);   // look-ahead budget in enemy-ticks
  var simCount = 0, tickCount = 0, workCount = 0;

  // Simulates from `src` (state at a wave start, after payment and purchases, before its spawns are queued)
  // with no further purchases and enemy HP inflated by `mu`.
  // Badness: FALL_BASE + (ticks the base falls before the horizon) if the base falls inside the horizon,
  // otherwise the HP-weighted leak damage of the enemies of the known waves (0 = nothing leaks).
  function runTest(src, limit, mu) {
    var w = src.wave, i, n, tr = 0;
    copyState(R, src);
    R.noFall = FALL_LEAK_W > 0; R.hpScale = mu; R.trackW = w + K_TRACK; R.pen = 0; R.leakDmg = 0;
    for (i = 0, n = R.n; i < n; i++) if (R.ety[i] !== DEAD) { tr++; if (mu !== 1) { R.ehp[i] *= mu; R.emx[i] *= mu; } }
    for (i = 0; i <= K_TRACK; i++) tr += comp(w + i).length;
    for (i = 0; i < R.sw.length; i++) tr += R.sw[i].comp.length - R.sw[i].next;
    R.trackedLeft = tr;
    queueWave(R, w, comp(w));
    var end = R.tick + TEST_MAX, end0 = end, lastW = w + K_TRACK + J_EXTRA, fallAt = -1, bad;
    simCount++;
    while (R.trackedLeft > 0 && R.tick < end) {
      if (R.tick > src.tick && (R.tick - 20) % 40 === 0) {
        payWave(R, R.wave + 1);
        if (R.wave <= lastW) queueWave(R, R.wave, comp(R.wave));
      }
      stepTick(R, null);
      tickCount++; workCount += R.n;
      if (R.fell) return FALL_BASE + (end - R.fallTick) + R.leakDmg * 0.01;
      if (fallAt < 0 && R.baseHp <= 0) { fallAt = R.tick - 1; if (fallAt + POST_FALL < end) end = fallAt + POST_FALL; }
      bad = fallAt < 0 ? R.leakDmg : FALL_BASE + (end0 - fallAt) + FALL_LEAK_W * R.leakDmg;
      if (bad > limit) return bad;
    }
    return fallAt < 0 ? R.leakDmg + PEN_W * R.pen : FALL_BASE + (end0 - fallAt) + FALL_LEAK_W * R.leakDmg;
  }

  // ------------------------------------------------------------------ purchase policy
  var MAX_ROUNDS = par("maxRounds", 16), SWAP_ROUNDS = par("swapRounds", 3), COST0 = par("cost0", 0);
  var FINAL = par("final", [1, 1, 1, 1, 1, 1, 1, 1, 2, 1, 4, 4, 4, 1, 4, 1]);
  var SWAP_TYPES = par("swapTypes", [0, 1, 2, 4]), RICH = par("rich", 700), SWAP_MIN_GAIN = par("swapMinGain", 3);
  var REFRESH = par("refresh", 1), REFRESH_TYPES = par("refreshTypes", [0, 1, 0, 1, 0]), REFRESH_MINCD = par("refreshMinCd", 6), REFRESH_MIN_GAIN = par("refreshMinGain", 0.5);
  var REFRESH_GOLD = par("refreshGold", 300), REFRESH_MAX = par("refreshMax", 6), REFRESH_KEEP = par("refreshKeep", 0);
  /*DEV*/var history = [];/*END_DEV*/

  function tierCost(t, from, to) {   // gold to take a turret of type t from tier `from` (0 = empty) to tier `to`
    var c = 0;
    for (var k = from + 1; k <= to; k++) c += k === 1 ? T_COST[t] : k === 2 ? T_COST[t] : 2 * T_COST[t];
    return c;
  }
  // puts slot s of state D at (type t, tier k), selling what is there if the type differs. Returns the list of ops.
  function setSlot(D, s, t, k, ops, refresh) {
    if (D.tty[s] >= 0 && (D.tty[s] !== t || refresh)) { applyAct(D, 2, s, 0); if (ops) ops.push({ op: "sell", slot: s }); }
    if (D.tty[s] < 0) { if (!applyAct(D, 0, s, t)) return false; if (ops) ops.push({ op: "build", slot: s, type: TNAMES[t] }); }
    while (D.ttr[s] < k) { if (!applyAct(D, 1, s, 0)) return false; if (ops) ops.push({ op: "upgrade", slot: s }); }
    return true;
  }
  var best = { score: 0, s: -1, t: -1, k: 0, m: 0 };
  function tryCand(s, t, k, mu, cur, floorGold) {
    var cost;
    if (W.tty[s] === t) cost = tierCost(t, W.ttr[s], k);
    else cost = tierCost(t, 0, k) - (W.tty[s] >= 0 ? Math.floor(W.tsp[s] * 70 / 100) : 0);
    if (W.gold - cost < floorGold) return;
    var eff = (cost < 20 ? 20 : cost) + COST0;
    copyState(C, W);
    if (!setSlot(C, s, t, k, null)) return;
    var m = runTest(C, cur - best.score * eff, mu);
    var sc = (cur - m) / eff;
    if (sc > best.score) { best.score = sc; best.s = s; best.t = t; best.k = k; best.m = m; }
  }

  function greedy(mu, floorGold, acts) {
    var rounds = 0, swaps = 0, s, t, k, i;
    var cur = runTest(W, 1e9, mu);
    while (cur > 0.5 && rounds < MAX_ROUNDS && acts.length < 26 && workCount < WORK_HARD) {
      rounds++;
      best.score = 0; best.s = -1;
      var rich = W.gold - floorGold >= RICH;
      for (s = 0; s < 16; s++) {
        t = W.tty[s];
        if (t < 0) {
          tryCand(s, FINAL[s], 1, mu, cur, floorGold);
          if (rich) tryCand(s, FINAL[s], 3, mu, cur, floorGold);
        } else if (W.ttr[s] < 3) {
          tryCand(s, t, W.ttr[s] + 1, mu, cur, floorGold);
          if (rich && W.ttr[s] === 1) tryCand(s, t, 3, mu, cur, floorGold);
        }
      }
      if (best.s < 0 && floorGold === 0 && swaps < SWAP_ROUNDS && workCount < WORK_SOFT) {
        // nothing left to add: try re-shaping the build (same tier, other type)
