(function () {
  // Exercises the audio paths: counts the nodes the page creates while PLAYING across many events.
  var $ = function (id) { return document.getElementById(id); };
  var AC = window.AudioContext || window.webkitAudioContext;
  if (!AC) return 'no AudioContext';
  var counts = { osc: 0, src: 0, gain: 0, pan: 0, started: 0, stopped: 0 }, states = [];
  var P = AC.prototype;
  ['createOscillator', 'createBufferSource', 'createGain', 'createStereoPanner'].forEach(function (name, i) {
    var orig = P[name], key = ['osc', 'src', 'gain', 'pan'][i];
    if (!orig) return;
    P[name] = function () { counts[key]++; var n = orig.apply(this, arguments); states.push(this.state); window.__ctx = this; return n; };
  });
  var out = [];
  function scrub(t) { var s = $('scrubber'); s.value = String(t); s.dispatchEvent(new Event('input', { bubbles: true })); }
  function play(t0, frames, speed) {
    scrub(t0);
    document.querySelector('.speed-pill[data-speed="' + speed + '"]').click();
    $('btn-toggle').click();
    var before = JSON.stringify(counts);
    window.__pump(1000 / 60, frames);
    out.push('play from ' + t0 + ' for ' + frames + ' frames at ' + speed + 'x: ' + before + ' -> ' + JSON.stringify(counts) + ' ctx=' + (window.__ctx ? window.__ctx.state : '?'));
    $('btn-toggle').click();
  }
  try {
    $('btn-toggle').click();                 // COUNTDOWN -> PAUSED
    play(0.5, 90, '1.0');                    // wave 1 start: horn, first shots, kills
    play(60, 120, '2.0');                    // busy mid game
    var fall = window.BENCH_REPORT.seed42.fallTick;
    if (fall > 0) { play(fall / 20 - 4.5, 240, '2.0'); play(fall / 20 - 0.5, 200, '1.0'); }   // leaks, then the fall and the wind
    scrub(10); window.__pump(1000 / 60, 30);
    out.push('after scrubbing while paused (no new nodes expected): ' + JSON.stringify(counts));
  } catch (e) { out.push('EXCEPTION ' + (e && e.stack || e)); }
  return out.join('\n');
})()

