const fs=require("fs"); const html=fs.readFileSync("/private/tmp/pcd-sbx-claude-fable-5.2-xhigh-r2-0wrfi1cq/work/index.html","utf8");
const m=[...html.matchAll(/<script(?: id="([^"]+)")?(?: src="([^"]+)")?>([\s\S]*?)<\/script>/g)];
console.log("scripts:", m.map(x => x[1] || (x[2] ? "src:" + x[2] : "main")).join(" | "));
const strat = m.find(x=>x[1]==="rampart-strategy")[3], sim = m.find(x=>x[1]==="rampart-sim")[3], main = m.find(x=>!x[1]&&!x[2])[3];
const cs = new Function(strat + "\nreturn createStrategy;")(); const rs = new Function(sim + "\nreturn rampartSimulate;")();
const A = () => ({ plan(s) { const a = []; let g = s.gold; for (const sl of s.slots) if (!sl.turret && g >= 50) { a.push({ op: "build", slot: sl.slot, type: "bolt" }); g -= 50; } return a; } });
const B = () => ({ plan(s) { if (s.wave === 1) return [{op:"build",slot:3,type:"cannon"},{op:"build",slot:6,type:"frost"}]; if (s.wave === 3) return [{op:"upgrade",slot:3},{op:"build",slot:12,type:"flak"}]; if (s.wave === 6) return [{op:"build",slot:8,type:"lance"},{op:"sell",slot:6}]; return []; } });
const ra = rs(A, 42, 12020), rb = rs(B, 7, 12020);
console.log("vector A:", ra.score, ra.fallTick, ra.log.length, ra.hash, ra.hash==="82a5353d" ? "MATCH" : "MISMATCH");
console.log("vector B:", rb.score, rb.fallTick, rb.log.length, rb.hash, rb.hash==="2e8858d7" ? "MATCH" : "MISMATCH");
const r42 = rs(cs, 42, 2020), full = rs(cs, 42, 12020);
console.log("strategy seed 42 (replay window):", r42.score, r42.fallTick, r42.hash, "| full game:", full.score, full.fallTick, full.hash);
console.log("in-file report:", (main.match(/meanScoreOnTestedSeeds: [0-9.]+/)||[])[0], (main.match(/seedsTested: \d+/)||[])[0], (main.match(/testedInBrowser: \w+/)||[])[0], (main.match(/measuredFps: \w+/)||[])[0]);
console.log("external refs:", [...html.matchAll(/(?:src|href)="(https?:[^"]+)"/g)].map(x=>x[1]).join(", "), "| fetch/XHR/WebSocket/TextureLoader/SRGBColorSpace/Math.random/Date.now in page:", ["fetch(","XMLHttpRequest","WebSocket","TextureLoader","SRGBColorSpace","Math.random","Date.now","<audio","importmap"].filter(t=>html.includes(t)));
console.log("size", html.length, "chars");
' 2>&1 | grep -v ERROR:; ls -la /private/tmp/pcd-sbx-claude-fable-5.2-xhigh-r2-0wrfi1cq/work/

